CREATE OR REPLACE FUNCTION public."help_articles_search_vector_update"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.search_vector := 
        setweight(to_tsvector('english', COALESCE(NEW.title, '')), 'A') ||
        setweight(to_tsvector('english', COALESCE(NEW.content, '')), 'B') ||
        setweight(to_tsvector('english', COALESCE(NEW.excerpt, '')), 'C') ||
        setweight(to_tsvector('english', COALESCE(NEW.tags::text, '')), 'D');
    RETURN NEW;
END;
$function$
;

create or replace view "public"."kpis" as  SELECT ik.id,
    i.organization_id,
    ik.name,
    NULL::real AS current_value,
    ik.target_value,
    ik.unit,
    NULL::text AS trend_direction,
    ik.measurement_frequency AS period,
    ik.updated_at
   FROM (initiative_kpis ik
     JOIN initiatives i ON ((ik.initiative_id = i.id)));

CREATE OR REPLACE FUNCTION public.llm_logs_compat_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.created_at IS NULL THEN NEW.created_at := COALESCE(NEW."timestamp", CURRENT_TIMESTAMP); END IF;
  IF NEW.total_tokens IS NULL THEN NEW.total_tokens := COALESCE(NEW.tokens_in, 0) + COALESCE(NEW.tokens_out, 0); END IF;
  IF NEW.error IS NULL AND NEW.error_message IS NOT NULL THEN NEW.error := NEW.error_message; END IF;
  IF NEW.tokens_used IS NULL THEN NEW.tokens_used := COALESCE(NEW.tokens_in, 0) + COALESCE(NEW.tokens_out, 0); END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public."notebook_pages_search_vector_update"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      BEGIN
        NEW.search_vector :=
          setweight(to_tsvector('simple', coalesce(NEW.title, '')), 'A') ||
          setweight(to_tsvector('simple', coalesce(NEW.content_text, '')), 'B') ||
          setweight(to_tsvector('simple', coalesce(NEW.tags_json, '')), 'C');
        RETURN NEW;
      END;
      $function$
;

CREATE OR REPLACE FUNCTION public.set_updated_at_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_conversation_on_message()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    UPDATE conversations 
    SET 
        message_count = message_count + 1,
        last_message_preview = LEFT(NEW.content, 200),
        last_message_at = NEW.created_at,
        updated_at = NOW()
    WHERE id = NEW.conversation_id;
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_conversation_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_mfa_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_modified_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$function$
;

create or replace view "public"."v_multi_framework_assessment_summary" as  SELECT mfa.id,
    mfa.project_id,
    mfa.organization_id,
    mfa.framework,
    mfa.name,
    mfa.status,
    mfa.overall_score,
    mfa.version,
    mfa.created_at,
    mfa.updated_at,
    ((u.first_name || ' '::text) || u.last_name) AS created_by_name,
    p.name AS project_name,
    o.name AS organization_name,
    ( SELECT count(*) AS count
           FROM multi_framework_assessment_reviewers r
          WHERE ((r.assessment_id)::text = mfa.id)) AS reviewer_count,
    ( SELECT count(*) AS count
           FROM multi_framework_assessment_reviewers r
          WHERE (((r.assessment_id)::text = mfa.id) AND ((r.status)::text = 'COMPLETED'::text))) AS completed_reviews,
    ( SELECT count(*) AS count
           FROM multi_framework_assessment_comments c
          WHERE (((c.assessment_id)::text = mfa.id) AND ((c.status)::text = 'OPEN'::text))) AS open_comments
   FROM (((multi_framework_assessments mfa
     LEFT JOIN users u ON (((mfa.created_by)::text = u.id)))
     LEFT JOIN projects p ON ((mfa.project_id = p.id)))
     LEFT JOIN organizations o ON ((mfa.organization_id = o.id)));

create or replace view "public"."v_pending_gate_decisions" as  SELECT gd.id,
    gd.assessment_id,
    gd.organization_id,
    gd.gate_type,
    gd.from_status,
    gd.to_status,
    gd.approver_role,
    gd.assignee_id,
    gd.status,
    gd.requested_at,
    gd.requested_by,
    gd.request_comment,
    gd.reminder_count,
    NULL::text AS assessment_type,
    a.status AS assessment_status,
    NULL::numeric AS completion_percent,
    NULL::numeric AS confidence_avg,
    COALESCE(NULLIF(TRIM(BOTH FROM concat_ws(' '::text, u_req.first_name, u_req.last_name)), ''::text), u_req.email, u_req.id) AS requester_name,
    u_req.email AS requester_email,
    COALESCE(NULLIF(TRIM(BOTH FROM concat_ws(' '::text, u_ass.first_name, u_ass.last_name)), ''::text), u_ass.email, u_ass.id) AS assignee_name,
    u_ass.email AS assignee_email,
    (EXTRACT(day FROM (now() - gd.requested_at)))::integer AS days_waiting
   FROM (((assessment_gate_decisions gd
     JOIN assessments a ON ((a.id = gd.assessment_id)))
     LEFT JOIN users u_req ON ((u_req.id = gd.requested_by)))
     LEFT JOIN users u_ass ON ((u_ass.id = gd.assignee_id)))
  WHERE (gd.status = 'PENDING'::text);

CREATE OR REPLACE FUNCTION public.z139_decode_html_entities(input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  cur TEXT := input;
  nxt TEXT;
  i INT;
BEGIN
  IF input IS NULL THEN RETURN NULL; END IF;
  FOR i IN 1..6 LOOP
    nxt := cur;
    nxt := replace(nxt, '&amp;', '&');
    nxt := replace(nxt, '&lt;', '<');
    nxt := replace(nxt, '&gt;', '>');
    nxt := replace(nxt, '&quot;', '"');
    nxt := replace(nxt, '&#x27;', '''');
    nxt := replace(nxt, '&apos;', '''');
    nxt := replace(nxt, '&#96;', '`');
    nxt := replace(nxt, '&nbsp;', ' ');
    EXIT WHEN nxt = cur;
    cur := nxt;
  END LOOP;
  RETURN cur;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.z139_deep_decode_json_text(input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  IF input IS NULL OR input = '' THEN RETURN input; END IF;
  RETURN (z139_deep_decode_jsonb(input::jsonb))::text;
EXCEPTION WHEN OTHERS THEN
  RETURN input;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.z139_deep_decode_jsonb(input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  result JSONB;
  k TEXT;
  v JSONB;
  arr JSONB[] := ARRAY[]::JSONB[];
  elem JSONB;
BEGIN
  IF input IS NULL THEN RETURN NULL; END IF;
  CASE jsonb_typeof(input)
    WHEN 'string' THEN
      RETURN to_jsonb(z139_decode_html_entities(input #>> '{}'));
    WHEN 'object' THEN
      result := '{}'::jsonb;
      FOR k, v IN SELECT * FROM jsonb_each(input) LOOP
        result := result || jsonb_build_object(k, z139_deep_decode_jsonb(v));
      END LOOP;
      RETURN result;
    WHEN 'array' THEN
      FOR elem IN SELECT * FROM jsonb_array_elements(input) LOOP
        arr := arr || z139_deep_decode_jsonb(elem);
      END LOOP;
      RETURN to_jsonb(arr);
    ELSE
      RETURN input;
  END CASE;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.z139_escape_html_once(input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE r TEXT;
BEGIN
  IF input IS NULL THEN RETURN NULL; END IF;
  -- Order matters: escape `&` FIRST, before introducing any new `&` from
  -- the other entities below (mirrors the single-pass JS regex in
  -- security.utils.ts sanitizeString).
  r := replace(input, '&', '&amp;');
  r := replace(r, '<', '&lt;');
  r := replace(r, '>', '&gt;');
  r := replace(r, '"', '&quot;');
  r := replace(r, '''', '&#x27;');
  r := replace(r, '`', '&#96;');
  RETURN r;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.z139_is_double_escaped(input text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT input IS NOT NULL
     AND input ~ '&amp;(amp|lt|gt|quot|apos|#x27|#96|nbsp);';
$function$
;

CREATE OR REPLACE FUNCTION public.z139_normalize_single_escape(input text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT z139_escape_html_once(z139_decode_html_entities(input));
$function$
;

create or replace view "public"."competency_usage_stats" as  SELECT c.id AS capability_id,
    c.organization_id,
    c.name,
    c.category_id,
    count(DISTINCT cr.initiative_id) AS initiative_count,
    count(DISTINCT uc.user_id) AS user_count
   FROM ((capabilities c
     LEFT JOIN capability_requirements cr ON ((cr.capability_id = c.id)))
     LEFT JOIN user_capabilities uc ON ((uc.capability_id = c.id)))
  WHERE (c.is_active = true)
  GROUP BY c.id, c.organization_id, c.name, c.category_id;

