-- ============================================================
-- T10 partner_* text->uuid alignment (base-DDL drift: autorun makes
-- partner_organizations.id / partner_certifications.id TEXT; TROLLEY=uuid).
-- Guarded by a type check => runs ONLY on fresh-env (text); no-op on demo
-- (already uuid) and on 2nd run. Lands the 11 partner FKs.
-- ============================================================
DO $t10uuid$
BEGIN
  IF (SELECT data_type FROM information_schema.columns WHERE table_schema='public' AND table_name='partner_organizations' AND column_name='id')='text' THEN
    ALTER TABLE public.partner_certificates DROP CONSTRAINT IF EXISTS partner_certificates_certification_id_fkey;
    ALTER TABLE public.partner_certificates DROP CONSTRAINT IF EXISTS partner_certificates_partner_org_id_fkey;
    ALTER TABLE public.partner_certifications DROP CONSTRAINT IF EXISTS partner_certifications_partner_org_id_fkey;
    ALTER TABLE public.partner_organizations ALTER COLUMN id TYPE uuid USING id::uuid;
    ALTER TABLE public.partner_organizations ALTER COLUMN id SET DEFAULT gen_random_uuid();
    ALTER TABLE public.partner_certifications ALTER COLUMN id TYPE uuid USING id::uuid;
    ALTER TABLE public.partner_certifications ALTER COLUMN id SET DEFAULT gen_random_uuid();
    ALTER TABLE public.partner_certifications ALTER COLUMN partner_org_id TYPE uuid USING partner_org_id::uuid;
    ALTER TABLE public.partner_certificates ALTER COLUMN partner_org_id TYPE uuid USING partner_org_id::uuid;
    ALTER TABLE public.partner_certificates ALTER COLUMN certification_id TYPE uuid USING certification_id::uuid;
    ALTER TABLE public.partner_certificates ADD CONSTRAINT partner_certificates_certification_id_fkey FOREIGN KEY (certification_id) REFERENCES partner_certifications(id) ON DELETE CASCADE;
    ALTER TABLE public.partner_certificates ADD CONSTRAINT partner_certificates_partner_org_id_fkey FOREIGN KEY (partner_org_id) REFERENCES partner_organizations(id) ON DELETE CASCADE;
    ALTER TABLE public.partner_certifications ADD CONSTRAINT partner_certifications_partner_org_id_fkey FOREIGN KEY (partner_org_id) REFERENCES partner_organizations(id) ON DELETE CASCADE;
    ALTER TABLE partner_activity_log ADD CONSTRAINT partner_activity_log_partner_org_id_fkey FOREIGN KEY (partner_org_id) REFERENCES partner_organizations(id) ON DELETE SET NULL;
    ALTER TABLE partner_client_organizations ADD CONSTRAINT partner_client_organizations_partner_org_id_fkey FOREIGN KEY (partner_org_id) REFERENCES partner_organizations(id) ON DELETE CASCADE;
    ALTER TABLE partner_commissions ADD CONSTRAINT partner_commissions_partner_org_id_fkey FOREIGN KEY (partner_org_id) REFERENCES partner_organizations(id) ON DELETE CASCADE;
    ALTER TABLE partner_invoices ADD CONSTRAINT partner_invoices_partner_org_id_fkey FOREIGN KEY (partner_org_id) REFERENCES partner_organizations(id) ON DELETE CASCADE;
    ALTER TABLE partner_learning_progress ADD CONSTRAINT partner_learning_progress_certification_id_fkey FOREIGN KEY (certification_id) REFERENCES partner_certifications(id) ON DELETE CASCADE;
    ALTER TABLE partner_licenses ADD CONSTRAINT partner_licenses_partner_org_id_fkey FOREIGN KEY (partner_org_id) REFERENCES partner_organizations(id) ON DELETE CASCADE;
    ALTER TABLE partner_projects ADD CONSTRAINT partner_projects_partner_org_id_fkey FOREIGN KEY (partner_org_id) REFERENCES partner_organizations(id) ON DELETE CASCADE;
    ALTER TABLE partner_regions ADD CONSTRAINT partner_regions_partner_org_id_fkey FOREIGN KEY (partner_org_id) REFERENCES partner_organizations(id) ON DELETE CASCADE;
    ALTER TABLE partner_resource_downloads ADD CONSTRAINT partner_resource_downloads_partner_org_id_fkey FOREIGN KEY (partner_org_id) REFERENCES partner_organizations(id) ON DELETE CASCADE;
    ALTER TABLE partner_specializations ADD CONSTRAINT partner_specializations_partner_org_id_fkey FOREIGN KEY (partner_org_id) REFERENCES partner_organizations(id) ON DELETE CASCADE;
    ALTER TABLE partner_users ADD CONSTRAINT partner_users_partner_org_id_fkey FOREIGN KEY (partner_org_id) REFERENCES partner_organizations(id) ON DELETE CASCADE;
  END IF;
END $t10uuid$;
